<h2>Novo produto</h2>
<?php if(!$categorias): ?><div class="alert error">Cadastre uma categoria antes de adicionar produtos.</div><a class="btn" href="<?= e(url('categorias','create')) ?>">Cadastrar categoria</a><?php else: ?>
<form class="panel" method="post" action="<?= e(url('produtos','save')) ?>"><input type="hidden" name="token" value="<?= e(token()) ?>"><label>Nome<input name="nome" required maxlength="255" value="<?= e($_POST['nome']??'') ?>"></label><label>Descrição<textarea name="descricao" rows="4"><?= e($_POST['descricao']??'') ?></textarea></label><label>Preço (R$)<input name="preco" type="number" step="0.01" min="0" max="99999999.99" required value="<?= e($_POST['preco']??'') ?>"></label><label>Categoria<select name="categoria_id" required><option value="">Selecione...</option><?php foreach($categorias as $c): ?><option value="<?= e($c['id']) ?>" <?= (string)($_POST['categoria_id']??'')===(string)$c['id']?'selected':'' ?>><?= e($c['nome']) ?></option><?php endforeach; ?></select></label><div class="buttons"><button class="btn" type="submit">Salvar produto</button><a class="btn secondary" href="<?= e(url('produtos')) ?>">Cancelar</a></div></form><?php endif; ?>
